import {test,expect} from '@playwright/test';
import {pressObservedLocalAction} from '../tests/browser/keyboardAdmission';
for(const width of [320,390,768,1280])for(const mode of ['before','after'])test(`${width}px native summary replacement ${mode} activation`,async({page})=>{
 await page.setViewportSize({width,height:900});
 await page.setContent(`<style>body{font:200% sans-serif}summary{min-height:44px}</style><details open><summary>Organization actions</summary><a href="#settings">Organization settings</a></details>`);
 await page.evaluate(mode=>{
  const first=document.querySelector('summary')!;const details=document.querySelector('details')!;
  document.documentElement.dataset.clicks='0';
  const replace=()=>first.replaceWith(first.cloneNode(true));
  document.addEventListener('click',()=>{document.documentElement.dataset.clicks=String(Number(document.documentElement.dataset.clicks)+1);},true);
  if(mode==='after')details.addEventListener('toggle',()=>{if(!details.open)replace();},{once:true});
  if(mode==='before')first.addEventListener('focus',replace,{once:true});
 },mode);
 await pressObservedLocalAction(page.locator('summary'));
 await expect(page.locator('details')).toHaveJSProperty('open',false);
 await expect(page.locator('html')).toHaveAttribute('data-clicks','1');
 await page.locator('summary').focus();await expect(page.locator('summary')).toBeFocused();
 await page.keyboard.press('Enter');await expect(page.getByRole('link',{name:'Organization settings'})).toBeVisible();
 await expect(page.locator('html')).toHaveAttribute('data-clicks','2');
 await page.screenshot({path:`work/organization-admission-native-${width}-${mode}.png`});
});
